/**
 * Regression tests for KS-1165: excludedPaths must carry the
 * `/api/v2/verification/verify` prefix (a startsWith match, so `/verify` and
 * `/verify-file`; not the whole `/api/v2/verification/*` family) so
 * cookie-bearing browser callers to the v2 verify endpoints aren't rejected
 * with `CSRF_TOKEN_MISSING`.
 */

import { describe, it, expect, vi, beforeEach, beforeAll, afterAll } from 'vitest';
import type { Request, Response } from 'express';
import express from 'express';
import cookieParser from 'cookie-parser';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { createCsrfMiddleware, csrfMiddleware } from '../middleware/csrf';
import { enforceJsonContentType } from '../middleware/contentType';

vi.mock('../utils/logger', () => ({
  logger: {
    warn: vi.fn(),
    error: vi.fn(),
    info: vi.fn(),
  },
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeReq(overrides: Partial<Request> = {}): Request {
  return {
    headers: {},
    cookies: {},
    body: {},
    query: {},
    path: '/api/documents',
    method: 'POST',
    ip: '127.0.0.1',
    ...overrides,
  } as unknown as Request;
}

function makeRes(): Response & { _status: number; _json: any } {
  const res: any = {
    _status: 0,
    _json: null,
    status(code: number) {
      this._status = code;
      return this;
    },
    json(payload: any) {
      this._json = payload;
      return this;
    },
    cookie: vi.fn(),
    setHeader: vi.fn(),
  };
  return res;
}

const { protect } = createCsrfMiddleware();

describe('KS-1165 — v2 verification paths are excluded from CSRF', () => {
  let next: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    next = vi.fn();
  });

  it('🔴 KS-1165 — POST /api/v2/verification/verify-file with a cookie is excluded from CSRF', () => {
    // Cookie-bearing caller of the v2 verify-file endpoint must be excluded
    // by the same startsWith rule that excludes v1's /api/verification/verify.
    const req = makeReq({
      path: '/api/v2/verification/verify-file',
      headers: { cookie: 'session=ambient', origin: 'http://localhost:6882' },
      cookies: { session: 'ambient' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(res._status).toBe(0);
  });

  it('🔴 KS-1165 — POST /api/v2/verification/verify with a cookie is excluded from CSRF', () => {
    const req = makeReq({
      path: '/api/v2/verification/verify',
      headers: { cookie: 'session=ambient', origin: 'http://localhost:6882' },
      cookies: { session: 'ambient' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(res._status).toBe(0);
  });

  it('KS-1165 control — the v1 path is excluded (before and after) and an unrelated cookie write is still rejected', () => {
    const reqV1 = makeReq({
      path: '/api/verification/verify-file',
      headers: { cookie: 'session=ambient', origin: 'http://localhost:6882' },
      cookies: { session: 'ambient' },
    });
    const resV1 = makeRes();
    protect(reqV1, resV1, next);
    expect(next).toHaveBeenCalledOnce();
    expect(resV1._status).toBe(0);

    next.mockClear();
    const reqOther = makeReq({
      path: '/api/documents',
      headers: { cookie: 'session=ambient', origin: 'http://localhost:6882' },
      cookies: { session: 'ambient' },
    });
    const resOther = makeRes();
    protect(reqOther, resOther, next);
    expect(next).not.toHaveBeenCalled();
    expect(resOther._status).toBe(403);
    expect(resOther._json.error.code).toBe('CSRF_TOKEN_MISSING');
  });
});

// ---------------------------------------------------------------------------
// KS-1165 DoD — "one gateway cell pins the chosen behaviour through the real
// mount order (CSRF then content-type)". Added by seat A beside the READY's
// unit cells, which call `protect` directly and so never meet the order.
//
// index.ts mounts cookieParser → csrfMiddleware.generateToken →
// csrfMiddleware.protect (outside NODE_ENV=test, :381-389) and only THEN
// enforceJsonContentType (:397). The first cell reads that order from index.ts
// itself; the others drive a cookie-only request through the same exported
// middlewares, in that order, to a terminal handler.
//
// These cells cannot see a regression in index.ts itself (the #1001 gate's
// T3 / T4). The real-app cells are in ks1165-real-app-csrf-mount-order.test.ts.
// ---------------------------------------------------------------------------

const GATEWAY_SRC = readFileSync(join(__dirname, '..', 'index.ts'), 'utf8');

describe('KS-1165 — v2 verify through the gateway mount order (CSRF, then content-type)', () => {
  let server: Server;
  let base: string;

  beforeAll(async () => {
    const app = express();
    app.use(cookieParser());
    app.use(csrfMiddleware.generateToken);
    app.use(csrfMiddleware.protect);
    app.use(enforceJsonContentType);
    const reached = (_req: Request, res: Response) => { res.status(200).json({ reached: true }); };
    app.post('/api/v2/verification/verify-file', reached);
    app.post('/api/v2/verification/verify', reached);
    app.post('/api/verification/verify-file', reached);
    app.post('/api/documents', reached);
    server = app.listen(0, '127.0.0.1');
    await new Promise<void>((r) => server.once('listening', () => r()));
    base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  });

  afterAll(async () => {
    await new Promise<void>((r) => server.close(() => r()));
  });

  const cookieOnly = (path: string, contentType: string, body: string) =>
    fetch(`${base}${path}`, {
      method: 'POST',
      headers: { cookie: 'session=ambient', 'content-type': contentType },
      body,
    });

  it('KS-1165 mount order — index.ts mounts csrfMiddleware.protect BEFORE enforceJsonContentType', () => {
    const csrfAt = GATEWAY_SRC.indexOf('app.use(csrfMiddleware.protect)');
    const contentTypeAt = GATEWAY_SRC.indexOf('app.use(enforceJsonContentType)');
    expect(csrfAt).toBeGreaterThan(-1);
    expect(contentTypeAt).toBeGreaterThan(-1);
    expect(csrfAt).toBeLessThan(contentTypeAt);
  });

  it('🔴 KS-1165 mount order — a cookie-only octet-stream POST /api/v2/verification/verify-file reaches the handler', async () => {
    const r = await cookieOnly('/api/v2/verification/verify-file', 'application/octet-stream', 'raw document bytes');
    expect(r.status).toBe(200);
    expect(await r.json()).toEqual({ reached: true });
  });

  it('🔴 KS-1165 mount order — a cookie-only JSON POST /api/v2/verification/verify reaches the handler', async () => {
    const r = await cookieOnly('/api/v2/verification/verify', 'application/json', JSON.stringify({ hash: 'a'.repeat(64) }));
    expect(r.status).toBe(200);
    expect(await r.json()).toEqual({ reached: true });
  });

  it('KS-1165 mount order control — v1 verify-file still reaches the handler, and a non-excluded path is refused by CSRF (403) before content-type (415)', async () => {
    const v1 = await cookieOnly('/api/verification/verify-file', 'application/octet-stream', 'raw document bytes');
    expect(v1.status).toBe(200);

    const other = await cookieOnly('/api/documents', 'application/octet-stream', 'raw document bytes');
    expect(other.status).toBe(403);
    expect((await other.json()).error.code).toBe('CSRF_TOKEN_MISSING');
  });
});

/**
 * Unit tests for the CSRF protection middleware (KS-428).
 *
 * The guard's rule is ambient authority: CSRF is enforced only for requests
 * that carry cookies and no header credential. Bearer / x-api-key requests
 * and cookie-less requests skip it — the former cannot be forged cross-site,
 * the latter carry nothing for a forger to ride (auth 401s them next, which
 * keeps the KS-3 401-not-403 contract for unauthenticated probes).
 * @module middleware/csrf
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { Request, Response } from 'express';
import { createCsrfMiddleware, getCsrfToken } from '../middleware/csrf';

vi.mock('../utils/logger', () => ({
  logger: {
    warn: vi.fn(),
    error: vi.fn(),
    info: vi.fn(),
  },
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeReq(overrides: Partial<Request> = {}): Request {
  return {
    headers: {},
    cookies: {},
    body: {},
    query: {},
    path: '/api/documents',
    method: 'POST',
    ip: '127.0.0.1',
    ...overrides,
  } as unknown as Request;
}

function makeRes(): Response & { _status: number; _json: any } {
  const res: any = {
    _status: 0,
    _json: null,
    status(code: number) {
      this._status = code;
      return this;
    },
    json(payload: any) {
      this._json = payload;
      return this;
    },
    cookie: vi.fn(),
    setHeader: vi.fn(),
  };
  return res;
}

const { protect } = createCsrfMiddleware();

// ---------------------------------------------------------------------------
// Skip rules — requests with no ambient authority never hit CSRF validation
// ---------------------------------------------------------------------------

describe('csrf protect — skip rules (no ambient authority)', () => {
  let next: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    next = vi.fn();
  });

  it('skips CSRF for Bearer-authenticated writes (the KS-428 inversion)', () => {
    // A bearer token lives in the client, never auto-attached cross-site —
    // this is the exact shape the inverted guard was wrongly blocking.
    const req = makeReq({
      headers: { authorization: 'Bearer some.jwt.token' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(res._status).toBe(0);
  });

  it('skips CSRF for Bearer writes even when cookies are also present', () => {
    // SPAs carry the XSRF-TOKEN cookie alongside their Bearer token; the
    // header credential is what authorises the request, so CSRF still skips.
    const req = makeReq({
      headers: { authorization: 'Bearer some.jwt.token', cookie: 'XSRF-TOKEN=abc' },
      cookies: { 'XSRF-TOKEN': 'abc' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
  });

  it('skips CSRF for x-api-key writes (connector / Platform S path)', () => {
    const req = makeReq({
      headers: { 'x-api-key': 'sk_test_key' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
  });

  it('skips CSRF for cookie-less unauthenticated writes so auth can 401 (KS-3)', () => {
    // No cookies → no ambient authority → nothing to forge. CSRF must not
    // pre-empt the auth middleware's 401 with a 403.
    const req = makeReq({ headers: {} });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(res._status).toBe(0);
  });

  it('skips CSRF for safe methods regardless of cookies', () => {
    const req = makeReq({
      method: 'GET',
      headers: { cookie: 'session=abc' },
      cookies: { session: 'abc' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
  });

  it('skips CSRF for excluded paths (auth lifecycle keeps its own defence)', () => {
    const req = makeReq({
      path: '/api/auth/refresh',
      headers: { cookie: 'refresh_token=abc' },
      cookies: { refresh_token: 'abc' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
  });
});

// ---------------------------------------------------------------------------
// Enforce rule — cookie-bearing writes without a header credential
// ---------------------------------------------------------------------------

describe('csrf protect — enforcement (cookies, no header credential)', () => {
  let next: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    next = vi.fn();
  });

  it('rejects a cookie-bearing write with no CSRF token (the forged shape)', () => {
    // The browser auto-attached a cookie but the page could not read/set the
    // CSRF header — the classic cross-site forgery. Must be blocked.
    const req = makeReq({
      headers: { cookie: 'session=ambient', origin: 'http://localhost:6882' },
      cookies: { session: 'ambient' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).not.toHaveBeenCalled();
    expect(res._status).toBe(403);
    expect(res._json.error.code).toBe('CSRF_TOKEN_MISSING');
  });

  it('rejects a cookie-bearing write whose header and cookie tokens differ', () => {
    const req = makeReq({
      headers: {
        cookie: 'XSRF-TOKEN=tok-a',
        'x-xsrf-token': 'tok-b-differs',
        origin: 'http://localhost:6882',
      },
      cookies: { 'XSRF-TOKEN': 'tok-a' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).not.toHaveBeenCalled();
    expect(res._status).toBe(403);
    // Same-length mismatched tokens → CSRF_TOKEN_MISMATCH; different lengths
    // throw inside timingSafeEqual → CSRF_TOKEN_INVALID. Either way: rejected.
    expect(['CSRF_TOKEN_MISMATCH', 'CSRF_TOKEN_INVALID']).toContain(res._json.error.code);
  });

  it('rejects a cookie-bearing write from a disallowed origin', () => {
    const req = makeReq({
      headers: { cookie: 'session=ambient', origin: 'https://evil.example' },
      cookies: { session: 'ambient' },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).not.toHaveBeenCalled();
    expect(res._status).toBe(403);
    expect(res._json.error.code).toBe('CSRF_ORIGIN_INVALID');
  });

  it('accepts a cookie-bearing write with a valid double-submit token pair', () => {
    // The legitimate browser flow: the real token in both the cookie and the
    // header, sent from an allowed origin.
    const seedReq = makeReq({ headers: { 'user-agent': 'vitest' } });
    const token = getCsrfToken(seedReq);
    const req = makeReq({
      headers: {
        cookie: `XSRF-TOKEN=${token}`,
        'x-xsrf-token': token,
        origin: 'http://localhost:6882',
        'user-agent': 'vitest',
      },
      cookies: { 'XSRF-TOKEN': token },
    });
    const res = makeRes();

    protect(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(res._status).toBe(0);
  });
});
